            val bankHash = ScarletVioletPseBankRestoreEditing.sha256(bank)
            require(entry.name == "switch_za_${bankHash}.pa9") {
                "The PSE Bank filename no longer matches its native PA9 bytes."
            }
            val destinationUri = selectedSourceUri
                ?: error("Reopen the selected Scarlet/Violet save from PSE.")
            val destination = readSelectedSwitchSource(destinationUri)
            require(ScarletVioletPseBankRestoreEditing.sha256(destination) == bound.snapshot.sourceSha256) {
                "The Scarlet/Violet source changed. Reopen it from PSE."
            }
            val review = LegendsZaToScarletVioletPk9.review(bank)
            require(review.sourceSpecies in ScarletVioletPokedexReadOnly.supportedSpecies(destination)) {
                "Species #${review.sourceSpecies} is not present in this Scarlet/Violet save's native Pokédex table."
            }
            review to bankHash
        }
        val opened = reviewed.getOrElse { error ->
            AlertDialog.Builder(this).setTitle("Legends: Z-A → Scarlet/Violet blocked")
                .setMessage(
                    (error.message ?: "This PA9 cannot be converted without unsupported loss.") +
                        "\n\nThe source save and PSE Bank entry remain unchanged."
                )
                .setPositiveButton("Close", null).show()
            return
        }
        val (review, openedHash) = opened
        val detail = buildString {
            append(
                review.sourceNickname.ifBlank { ScarletVioletSpeciesNames.name(review.sourceSpecies) } +
                    " (#${review.sourceSpecies})\n"
            )
            append("Reviewed Bank SHA-256: " + openedHash + "\n\n")
            append("Explicit PSE Legalise effects\n• ")
            append(review.effects.joinToString("\n• "))
            append(
                "\n\nChoose Legalise only to create the disclosed PK9 and then choose one empty " +
                    "native Scarlet/Violet PC-box slot. The source save and PA9 Bank entry remain unchanged. " +
                    "The destination is written to a new save copy, reopened, and verified; failure restores both sides " +
                    "and retains the recovery backup. This conversion does not claim an official HOME transfer, trade, " +
                    "encounter, ability, Tera, moveset, or provenance."
            )
        }
        val dialog = AlertDialog.Builder(this)
            .setTitle("PSE Bank • Legends: Z-A → Scarlet/Violet")
            .setMessage(detail)
            .setNegativeButton("Close", null)
            .setPositiveButton("Legalise & choose destination", null)
            .create()
        dialog.setOnShowListener {
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener {
                try {
                    require(session === bound) { "The active save changed. Reopen PSE Bank." }
                    val destinationUri = selectedSourceUri
                        ?: error("Reopen the selected Scarlet/Violet save from PSE.")
                    require(
                        entry.parentFile == directory &&
                            entry.name.startsWith("switch_za_") &&
                            entry.extension.equals("pa9", true)
                    ) { "This is not a current Legends: Z-A PSE Bank entry." }
                    val bank = entry.readBytes()
                    val bankHash = ScarletVioletPseBankRestoreEditing.sha256(bank)
                    require(bankHash == openedHash &&
                        entry.name == "switch_za_${bankHash}.pa9") {
                        "The exact reviewed PSE Bank entry changed. Reopen PSE Bank."
                    }
                    val current = readSelectedSwitchSource(destinationUri)
                    require(ScarletVioletPseBankRestoreEditing.sha256(current) == bound.snapshot.sourceSha256) {
                        "The Scarlet/Violet source changed. Reopen it from PSE."
                    }
                    val currentReview = LegendsZaToScarletVioletPk9.review(bank)
                    require(currentReview.sourceSpecies in ScarletVioletPokedexReadOnly.supportedSpecies(current)) {
                        "Species #${currentReview.sourceSpecies} is not present in this Scarlet/Violet save's native Pokédex table."
                    }
                    dialog.dismiss()
                    startActivity(
                        Intent(this, SwitchScarletVioletPseBankRestoreActivity::class.java)
                            .setData(destinationUri)
                            .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                            .putExtra("pse.bank.entry", entry.name)
                            .putExtra("pse.bank.sha256", openedHash)
                            .putExtra("pse.bank.legalise", true)
                            .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                    )
                } catch (error: Exception) {
                    AlertDialog.Builder(this).setTitle("Could not prepare Legalise conversion")
                        .setMessage(error.message ?: "The source and Bank entry were left unchanged.")
                        .setPositiveButton("Close", null).show()
                }
            }
        }
        dialog.show()
    }

    private fun showScarletVioletBankEntry(bound: SwitchReadSession, file: File) {
        if (session !== bound) return
        val directory = File(filesDir, "pse_bank").canonicalFile
        val entry = file.canonicalFile
        val parsed = runCatching {
            require(entry.parentFile == directory && entry.name.startsWith("switch_sv_") && entry.extension == "pk9") {
                "This is not a Scarlet/Violet Bank entry."
            }
            ScarletVioletPokemonReadOnly.read(entry.readBytes())
        }.getOrElse { ScarletVioletSlotRead.Invalid(it.message ?: "The Bank entry could not be read.") }
        if (parsed !is ScarletVioletSlotRead.Pokemon) {
            AlertDialog.Builder(this).setTitle("Unreadable PSE Bank entry")
                .setMessage((parsed as? ScarletVioletSlotRead.Invalid)?.reason ?: "The Bank entry is empty.")
                .setPositiveButton("Close", null).show()
            return
        }
        val p = parsed.value
        val detail = buildString {
            append("${ScarletVioletSpeciesNames.name(p.species)} (#${p.species}) • Form ${p.form}\n")
            append("Nickname: ${p.nickname.ifBlank { "None" }}\n")
            append("Shiny: ${if (p.shiny) "Yes" else "No"} • Egg: ${if (p.isEgg) "Yes" else "No"}\n")
            append("Original trainer: ${p.originalTrainer}\n\n")
            append("Native PK9 checksum passed. Restore writes the exact Bank record only to a reviewed new save copy; the active source and Bank entry remain unchanged. Removing this Bank copy never changes the Switch save.")
        }
        val dialog = AlertDialog.Builder(this).setTitle("PSE Bank • Scarlet/Violet")
            .setMessage(detail).setNegativeButton("Close", null).create()
        dialog.setButton(AlertDialog.BUTTON_POSITIVE, "Remove from PSE Bank",
            null as android.content.DialogInterface.OnClickListener?)
        dialog.setButton(AlertDialog.BUTTON_NEUTRAL, "Restore to new save copy",
            null as android.content.DialogInterface.OnClickListener?)
        dialog.setOnShowListener {
            dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener {
                try {
                    require(session === bound) { "The active save changed. Reopen PSE Bank." }
                    val source = selectedSourceUri ?: error("Reopen the selected Scarlet/Violet save from PSE.")
                    require(entry.parentFile == directory && entry.name.startsWith("switch_sv_") && entry.extension == "pk9") {
                        "This is not a current Scarlet/Violet Bank entry."
                    }
                    require(ScarletVioletPokemonReadOnly.read(entry.readBytes()) is ScarletVioletSlotRead.Pokemon) {
                        "The Bank record is invalid and cannot be restored."
                    }
                    dialog.dismiss()
                    startActivity(Intent(this, SwitchScarletVioletPseBankRestoreActivity::class.java).setData(source)
                        .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                        .putExtra("pse.bank.entry", entry.name)
                        .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION))
                } catch (error: Exception) {
                    AlertDialog.Builder(this).setTitle("Could not prepare Bank restore")
                        .setMessage(error.message ?: "The source and Bank entry were left unchanged.")
                        .setPositiveButton("Close", null).show()
                }
            }
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener {
                try {
                    require(session === bound) { "The active save changed; the Bank entry was left unchanged." }
                    require(entry.parentFile == directory && entry.name.startsWith("switch_sv_") && entry.extension == "pk9") {
                        "This is not a removable Scarlet/Violet Bank entry."
                    }
                    require(ScarletVioletPokemonReadOnly.read(entry.readBytes()) is ScarletVioletSlotRead.Pokemon) {
                        "The Bank record is invalid; it was left unchanged."
                    }
                    require(entry.delete()) { "The Bank entry could not be removed." }
                    dialog.dismiss()
                    AlertDialog.Builder(this).setTitle("Removed from PSE Bank")
                        .setMessage(entry.name + " was removed. The Switch save was not changed.")
                        .setPositiveButton("Back to Bank") { _, _ -> if (session === bound) showScarletVioletBank(bound) }
                        .setNegativeButton("Close", null).show()
                } catch (error: Exception) {
                    AlertDialog.Builder(this).setTitle("Could not remove Bank entry")
                        .setMessage(error.message ?: "The entry was left unchanged.")
                        .setPositiveButton("Close", null).show()
                }
            }
        }
        dialog.show()
    }
    private fun showLegendsZaBank(bound: SwitchReadSession) {
        if (session !== bound) return
        val directory = File(filesDir, "pse_bank")
        val entries = directory.listFiles()?.filter {
            it.isFile && (
                (it.name.startsWith("switch_za_") && it.extension.equals("pa9", true)) ||
                    (it.name.startsWith("pse1_") && it.extension.equals("pse1", true)) ||
                    it.extension.equals("pse2", true) ||
                    it.extension.equals("pk3", true) ||
                    it.extension.equals("pk4", true) ||
                    it.extension.equals("pk5", true) ||
                    it.extension.equals("pk6", true) ||
                    (it.name.startsWith("switch_swsh_") && it.extension.equals("pk8", true)) ||
                    (it.name.startsWith("switch_bdsp_") && it.extension.equals("pb8", true)) ||
                    (it.name.startsWith("switch_pla_") && it.extension.equals("pa8", true)) ||
                    it.extension.equals("pk7", true) ||
                    (it.name.startsWith("switch_lgpe_") && it.extension.equals("pb7", true)) ||
                    (it.name.startsWith("switch_sv_") && it.extension.equals("pk9", true))
                )
        }?.sortedWith(compareBy<File>({
            when {
                it.extension.equals("pa9", true) -> 0
                it.extension.equals("pse1", true) -> 1
                it.extension.equals("pse2", true) -> 2
                it.extension.equals("pk3", true) -> 3
                it.extension.equals("pk4", true) -> 4
                it.extension.equals("pk5", true) -> 5
                it.extension.equals("pk6", true) -> 6
                it.extension.equals("pk8", true) -> 7
                it.extension.equals("pb8", true) -> 8
                it.extension.equals("pa8", true) -> 9
                it.extension.equals("pk7", true) -> 10
                it.extension.equals("pb7", true) -> 11
                else -> 12
            }
        }, { it.name })).orEmpty()
        val labels = entries.map { file ->
            if (file.extension.equals("pse1", true)) {
                runCatching { Gen1ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank {
                            ScarletVioletSpeciesNames.name(source.species)
                        } + " (#" + source.species + ") • Gen 1 PSE1 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 1 PSE1 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pse2", true)) {
                runCatching { Gen2ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank {
                            ScarletVioletSpeciesNames.name(source.species)
                        } + " (#" + source.species + ") • Gen 2 PSE2 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 2 PSE2 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk3", true)) {
                runCatching { Gen3ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank {
                            ScarletVioletSpeciesNames.name(source.species)
                        } + " (#" + source.species + ") • Gen 3 PK3 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 3 PK3 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk4", true)) {
                runCatching { Gen4ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank {
                            ScarletVioletSpeciesNames.name(source.species)
                        } + " (#" + source.species + ") • Gen 4 PK4 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 4 PK4 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk5", true)) {
                runCatching { Gen5ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank {
                            ScarletVioletSpeciesNames.name(source.species)
                        } + " (#" + source.species + ") • Gen 5 PK5 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 5 PK5 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk6", true)) {
                runCatching { Gen6ToLegendsZaPa9.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank {
                            ScarletVioletSpeciesNames.name(source.species)
                        } + " (#" + source.species + ") • Gen 6 PK6 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 6 PK6 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pa9", true)) {
                val parsed = runCatching { LegendsZaPokemonReadOnly.read(file.readBytes()) }.getOrNull()
                val pokemon = (parsed as? LegendsZaSlotRead.Pokemon)?.value
                if (pokemon == null) file.name + " • unreadable"
                else pokemon.nickname.ifBlank { ScarletVioletSpeciesNames.name(pokemon.species) } +
                    " (#" + pokemon.species + ")" + (if (pokemon.shiny) " • Shiny" else "") +
                    (if (pokemon.isAlpha) " • Alpha" else "") + (if (pokemon.isEgg) " • Egg" else "") + " • PA9"
            } else if (file.extension.equals("pk8", true)) {
                runCatching { SwordShieldToLegendsZaPa9.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { SwordShieldSpeciesNames.name(review.sourceSpecies) } +
                            " (#${review.sourceSpecies}) • Sword/Shield PK8 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Sword/Shield PK8 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pb8", true)) {
                runCatching { BdspToLegendsZaPa9.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { SwordShieldSpeciesNames.name(review.sourceSpecies) } +
                            " (#${review.sourceSpecies}) • BDSP PB8 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • BDSP PB8 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pa8", true)) {
                runCatching { LegendsArceusToLegendsZaPa9.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { LegendsArceusSpeciesNames.name(review.sourceSpecies) } +
                            " (#${review.sourceSpecies}) • Legends: Arceus PA8 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Legends: Arceus PA8 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pb7", true)) {
                runCatching { LetsGoToLegendsZaPa9.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { ScarletVioletSpeciesNames.name(review.sourceSpecies) } +
                            " (#${review.sourceSpecies}) • Let's Go PB7 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Let's Go PB7 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk7", true)) {
                runCatching { Gen7ToLegendsZaPa9.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { ScarletVioletSpeciesNames.name(review.sourceSpecies) } +
                            " (#${review.sourceSpecies}) • Gen 7 PK7 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 7 PK7 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else {
                runCatching { ScarletVioletToLegendsZaPa9.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { ScarletVioletSpeciesNames.name(review.sourceSpecies) } +
                            " (#${review.sourceSpecies}) • Scarlet/Violet PK9 → PA9 • Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Scarlet/Violet PK9 blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            }
        }
        val builder = AlertDialog.Builder(this)
            .setTitle("PSE Bank • " + entries.size + " Legends: Z-A-compatible entries")
            .setPositiveButton("Close", null)
        if (entries.isEmpty()) {
            builder.setMessage(
                "No native Legends: Z-A PA9, eligible Gen 1 PSE1, eligible Gen 2 PSE2, eligible Gen 3 PK3, eligible Gen 4 PK4, eligible Gen 5 PK5, eligible Gen 6 PK6, Sword/Shield PK8, BDSP PB8, Legends: Arceus PA8, Generation 7 PK7, Let's Go PB7, or Scarlet/Violet PK9 entries are stored. " +
                    "Open Pokémon Boxes in a supported title, choose a Pokémon, then tap Add to PSE Bank."
            )
        } else {
            builder.setItems(labels.toTypedArray()) { _, index ->
                if (session === bound) {
                    val entry = entries[index]
                    when {
                        entry.extension.equals("pse1", true) ->
                            showLegendsZaGen1BankEntry(bound, entry)
                        entry.extension.equals("pse2", true) ->
                            showLegendsZaGen2BankEntry(bound, entry)
                        entry.extension.equals("pk3", true) ->
                            showLegendsZaGen3BankEntry(bound, entry)
                        entry.extension.equals("pk4", true) ->
                            showLegendsZaGen4BankEntry(bound, entry)
                        entry.extension.equals("pk5", true) ->
                            showLegendsZaGen5BankEntry(bound, entry)
                        entry.extension.equals("pk6", true) ->
                            showLegendsZaGen6BankEntry(bound, entry)
                        entry.extension.equals("pk8", true) ->
                            showLegendsZaSwordShieldBankEntry(bound, entry)
                        entry.extension.equals("pb8", true) ->
                            showLegendsZaBdspBankEntry(bound, entry)
                        entry.extension.equals("pa8", true) ->
                            showLegendsZaLegendsArceusBankEntry(bound, entry)
                        entry.extension.equals("pk7", true) ->
                            showLegendsZaGen7BankEntry(bound, entry)
                        entry.extension.equals("pb7", true) ->
                            showLegendsZaLetsGoBankEntry(bound, entry)
                        entry.extension.equals("pk9", true) ->
                            showLegendsZaScarletVioletBankEntry(bound, entry)
                        else -> showLegendsZaBankEntry(bound, entry)
                    }
                }
            }
        }
        builder.show()
    }

    private fun showLegendsZaGen1BankEntry(
        bound: SwitchReadSession,
        file: File
    ) {
        if (session !== bound) return
        val directory = File(filesDir, "pse_bank").canonicalFile
        val entry = runCatching { file.canonicalFile }.getOrNull()
        val opened = runCatching {
            require(entry != null && entry.parentFile == directory && entry.isFile &&
                entry.name.startsWith("pse1_") && entry.extension.equals("pse1", true)) {
                "This is not a current Gen 1 PSE Bank entry."
            }
            val bytes = entry.readBytes()
            val source = Gen1ToSwordShieldPk8.inspectSource(bytes)
            val destination = bound.snapshot.bytesCopy()
            val trainer = LegendsZaTrainerReadOnly.read(destination)
            require(trainer.languageId == 2) {
                "This bounded Gen 1 route currently requires an English Legends: Z-A destination trainer."
            }
            require(source.species in LegendsZaPokedexReadOnly.supportedSpecies(destination)) {
                "Species #" + source.species +
                    " is not present in this Legends: Z-A save's native Pokédex table."
            }
            Triple(bytes, source, trainer)
        }.getOrElse {
            AlertDialog.Builder(this).setTitle("Gen 1 -> Legends: Z-A blocked")
                .setMessage((it.message ?: "No safe conversion is available.") +
                    "\n\nThe PSE1 Bank entry and Legends: Z-A save remain unchanged.")
                .setPositiveButton("Close", null).show()
            return
        }
        val selected = entry ?: return
        val openedHash = LegendsZaPseBankRestoreEditing.sha256(opened.first)
        val loading = AlertDialog.Builder(this)
            .setTitle("Prepare Gen 1 -> Legends: Z-A")
            .setMessage("Loading documented species metadata and building a deterministic reviewed PA9 preview…")
            .setCancelable(false).create()
        loading.show()
        reader.execute {
            val prepared = runCatching {
                val metadata = loadGen1SwordShieldMetadata(opened.second.species)
                require(session === bound) { "The active save changed. Reopen PSE Bank." }
                val current = selected.readBytes()
                require(LegendsZaPseBankRestoreEditing.sha256(current) == openedHash) {
                    "The Gen 1 Bank entry changed during review."
                }
                metadata to Gen1ToLegendsZaPa9.review(
                    current, opened.third, metadata
                )
            }
            runOnUiThread {
                if (loading.isShowing) loading.dismiss()
                if (isFinishing || isDestroyed) return@runOnUiThread
                prepared.onSuccess { (metadata, converted) ->
                    val p = LegendsZaPseBankRestoreEditing
                        .inspectBankRecord(converted.nativeRecord)
                    val message = buildString {
                        append(ScarletVioletSpeciesNames.name(p.species) + " (#" +
                            p.species + ") • Level " + p.cachedLevel + "\n")
                        append("Source: " + selected.name +
                            " • preserved 63-byte PSE1 record\n")
                        append("Prepared destination: checksum-valid 344-byte native Legends: Z-A PA9\n\n")
                        append("Exact disclosed conversion effects\n• ")
                        append(converted.effects.joinToString("\n• "))
                        append("\n\nContinue only if you accept every disclosed Legalise effect.")
                    }
                    AlertDialog.Builder(this)
                        .setTitle("Gen 1 -> Legends: Z-A • PSE Legalise review")
                        .setMessage(message).setNegativeButton("Cancel", null)
                        .setPositiveButton("Legalise & choose destination") { _, _ ->
                            try {
                                require(session === bound) {
                                    "The active save changed. Reopen PSE Bank."
                                }
                                val source = selectedSourceUri ?: error(
                                    "Reopen the selected Legends: Z-A save from PSE."
                                )
                                require(selected.parentFile == directory && selected.isFile &&
                                    selected.name.startsWith("pse1_") &&
                                    selected.extension.equals("pse1", true)) {
                                    "The Gen 1 Bank entry changed."
                                }
                                val current = selected.readBytes()
                                require(
                                    LegendsZaPseBankRestoreEditing.sha256(current) ==
                                        openedHash
                                ) {
                                    "The Gen 1 Bank entry changed. Reopen PSE Bank."
                                }
                                val destination = readSelectedSwitchSource(source)
                                require(
                                    LegendsZaPseBankRestoreEditing.sha256(destination) ==
                                        bound.snapshot.sourceSha256
                                ) {
                                    "The Legends: Z-A source changed. Reopen it from PSE."
                                }
                                require(
                                    opened.second.species in
                                        LegendsZaPokedexReadOnly.supportedSpecies(destination)
                                ) {
                                    "The selected species is not present in this Legends: Z-A save's native Pokédex table."
                                }
                                Gen1ToLegendsZaPa9.review(
                                    current, LegendsZaTrainerReadOnly.read(destination), metadata
                                )
                                startActivity(Intent(
                                    this,
                                    SwitchLegendsZaPseBankRestoreActivity::class.java
                                )
                                    .setData(source)
                                    .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                                    .putExtra("pse.bank.entry", selected.name)
                                    .putExtra("pse.bank.legalise", true)
                                    .putExtra("pse.gen1.friendship", metadata.baseFriendship)
                                    .putExtra("pse.gen1.gender_rate", metadata.genderRate)
                                    .putExtra("pse.gen1.ability_id", metadata.abilityId)
                                    .putExtra("pse.gen1.ability_number", metadata.abilityNumber)
                                    .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION))
                            } catch (error: Exception) {
                                AlertDialog.Builder(this)
                                    .setTitle("Could not prepare Gen 1 conversion")
                                    .setMessage(error.message ?: "Both sources remain unchanged.")
                                    .setPositiveButton("Close", null).show()
                            }
                        }.show()
                }.onFailure {
                    AlertDialog.Builder(this).setTitle("Gen 1 -> Legends: Z-A blocked")
                        .setMessage((it.message ?: "No safe conversion is available.") +
                            "\n\nThe PSE1 Bank entry and Legends: Z-A save remain unchanged.")
                        .setPositiveButton("Close", null).show()
                }
            }
        }
    }

    private fun showLegendsZaGen2BankEntry(
        bound: SwitchReadSession,
        file: File
    ) {
        if (session !== bound) return
        val directory = File(filesDir, "pse_bank").canonicalFile
