    private fun showLegendsZaBankEntry(bound: SwitchReadSession, file: File) {
        if (session !== bound) return
        val directory = File(filesDir, "pse_bank").canonicalFile
        val entry = file.canonicalFile
        val parsed = runCatching {
            require(entry.parentFile == directory && entry.name.startsWith("switch_za_") && entry.extension == "pa9") {
                "This is not a Legends: Z-A Bank entry."
            }
            LegendsZaPokemonReadOnly.read(entry.readBytes())
        }.getOrElse { LegendsZaSlotRead.Invalid(it.message ?: "The Bank entry could not be read.") }
        if (parsed !is LegendsZaSlotRead.Pokemon) {
            AlertDialog.Builder(this).setTitle("Unreadable PSE Bank entry")
                .setMessage((parsed as? LegendsZaSlotRead.Invalid)?.reason ?: "The Bank entry is empty.")
                .setPositiveButton("Close", null).show()
            return
        }
        val p = parsed.value
        val detail = buildString {
            append("${ScarletVioletSpeciesNames.name(p.species)} (#${p.species}) • Form ${p.form}\n")
            append("Nickname: ${p.nickname.ifBlank { "None" }}\n")
            append("Shiny: ${if (p.shiny) "Yes" else "No"} • Alpha: ${if (p.isAlpha) "Yes" else "No"} • Egg: ${if (p.isEgg) "Yes" else "No"}\n")
            append("Original trainer: ${p.originalTrainer}\n\n")
            append("Native PA9 checksum passed. Restore writes the exact Bank record only to a reviewed new save copy; the active source and Bank entry remain unchanged. Removing this Bank copy never changes the Switch save.")
        }
        val dialog = AlertDialog.Builder(this).setTitle("PSE Bank • Legends: Z-A")
            .setMessage(detail).setNegativeButton("Close", null).create()
        dialog.setButton(AlertDialog.BUTTON_POSITIVE, "Remove from PSE Bank",
            null as android.content.DialogInterface.OnClickListener?)
        dialog.setButton(AlertDialog.BUTTON_NEUTRAL, "Restore to new save copy",
            null as android.content.DialogInterface.OnClickListener?)
        dialog.setOnShowListener {
            dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener {
                try {
                    require(session === bound) { "The active save changed. Reopen PSE Bank." }
                    val source = selectedSourceUri ?: error("Reopen the selected Legends: Z-A save from PSE.")
                    require(entry.parentFile == directory && entry.name.startsWith("switch_za_") && entry.extension == "pa9") {
                        "This is not a current Legends: Z-A Bank entry."
                    }
                    require(LegendsZaPokemonReadOnly.read(entry.readBytes()) is LegendsZaSlotRead.Pokemon) {
                        "The Bank record is invalid and cannot be restored."
                    }
                    dialog.dismiss()
                    startActivity(Intent(this, SwitchLegendsZaPseBankRestoreActivity::class.java).setData(source)
                        .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                        .putExtra("pse.bank.entry", entry.name)
                        .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION))
                } catch (error: Exception) {
                    AlertDialog.Builder(this).setTitle("Could not prepare Bank restore")
                        .setMessage(error.message ?: "The source and Bank entry were left unchanged.")
                        .setPositiveButton("Close", null).show()
                }
            }
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener {
                try {
                    require(session === bound) { "The active save changed; the Bank entry was left unchanged." }
                    require(entry.parentFile == directory && entry.name.startsWith("switch_za_") && entry.extension == "pa9") {
                        "This is not a removable Legends: Z-A Bank entry."
                    }
                    require(LegendsZaPokemonReadOnly.read(entry.readBytes()) is LegendsZaSlotRead.Pokemon) {
                        "The Bank record is invalid; it was left unchanged."
                    }
                    require(entry.delete()) { "The Bank entry could not be removed." }
                    dialog.dismiss()
                    AlertDialog.Builder(this).setTitle("Removed from PSE Bank")
                        .setMessage(entry.name + " was removed. The Switch save was not changed.")
                        .setPositiveButton("Back to Bank") { _, _ -> if (session === bound) showLegendsZaBank(bound) }
                        .setNegativeButton("Close", null).show()
                } catch (error: Exception) {
                    AlertDialog.Builder(this).setTitle("Could not remove Bank entry")
                        .setMessage(error.message ?: "The entry was left unchanged.")
                        .setPositiveButton("Close", null).show()
                }
            }
        }
        dialog.show()
    }
    private fun showSwordShieldBank(bound: SwitchReadSession) {
        if (session !== bound) return
        val directory = File(filesDir, "pse_bank")
        val entries = directory.listFiles()?.filter {
            it.isFile && ((it.name.startsWith("switch_swsh_") && it.extension.equals("pk8", true)) ||
                (it.name.startsWith("pse1_") && it.extension.equals("pse1", true)) ||
                it.extension.equals("pse2", true) ||
                it.extension.equals("pk3", true) ||
                it.extension.equals("pk4", true) ||
                it.extension.equals("pk5", true) ||
                it.extension.equals("pk6", true) ||
                it.extension.equals("pk7", true) ||
                (it.name.startsWith("switch_lgpe_") && it.extension.equals("pb7", true)) ||
                (it.name.startsWith("switch_bdsp_") && it.extension.equals("pb8", true)) ||
                (it.name.startsWith("switch_pla_") && it.extension.equals("pa8", true)) ||
                (it.name.startsWith("switch_sv_") && it.extension.equals("pk9", true)) ||
                (it.name.startsWith("switch_za_") && it.extension.equals("pa9", true)))
        }?.sortedWith(compareBy<File>({
            when {
                it.extension.equals("pk8", true) -> 0
                it.extension.equals("pse1", true) -> 1
                it.extension.equals("pse2", true) -> 2
                it.extension.equals("pk3", true) -> 3
                it.extension.equals("pk4", true) -> 4
                it.extension.equals("pk5", true) -> 5
                it.extension.equals("pk6", true) -> 6
                it.extension.equals("pk7", true) -> 7
                it.extension.equals("pb7", true) -> 8
                it.extension.equals("pb8", true) -> 9
                it.extension.equals("pa8", true) -> 10
                it.extension.equals("pk9", true) -> 11
                else -> 12
            }
        }, { it.name })).orEmpty()
        val labels = entries.map { file ->
            if (file.extension.equals("pse1", true)) {
                runCatching { Gen1ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank { SwordShieldSpeciesNames.name(source.species) } +
                            " (#" + source.species + ") • Gen 1 PSE1 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 1 route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pse2", true)) {
                runCatching { Gen2ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank { SwordShieldSpeciesNames.name(source.species) } +
                            " (#" + source.species + ") • Gen 2 PSE2 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 2 route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk3", true)) {
                runCatching { Gen3ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank { SwordShieldSpeciesNames.name(source.species) } +
                            " (#" + source.species + ") • Gen 3 PK3 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 3 route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk4", true)) {
                runCatching { Gen4ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank { SwordShieldSpeciesNames.name(source.species) } +
                            " (#" + source.species + ") • Gen 4 PK4 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 4 route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk5", true)) {
                runCatching { Gen5ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank { SwordShieldSpeciesNames.name(source.species) } +
                            " (#" + source.species + ") • Gen 5 PK5 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 5 route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk6", true)) {
                runCatching { Gen6ToSwordShieldPk8.inspectSource(file.readBytes()) }.fold(
                    onSuccess = { source ->
                        source.nickname.ifBlank { SwordShieldSpeciesNames.name(source.species) } +
                            " (#" + source.species + ") • Gen 6 PK6 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Gen 6 route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk7", true)) {
                val converted = runCatching { Gen7ToSwordShieldPk8.review(file.readBytes()) }
                converted.fold(
                    onSuccess = {
                        val p = SwordShieldPseBankRestoreEditing.inspectBankRecord(it.nativeRecord)
                        p.nickname.ifBlank { SwordShieldSpeciesNames.name(p.species) } +
                            " (#" + p.species + ") • Gen 7 PK7 -> PK8 Legalise"
                    },
                    onFailure = { file.name + " • Gen 7 route blocked • " + (it.message ?: "unreadable") }
                )
            } else if (file.extension.equals("pb7", true)) {
                runCatching { LetsGoToSwordShieldPk8.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { SwordShieldSpeciesNames.name(review.sourceSpecies) } +
                            " (#" + review.sourceSpecies + ") • Let's Go PB7 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Let's Go route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pb8", true)) {
                runCatching { BdspToSwordShieldPk8.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { SwordShieldSpeciesNames.name(review.sourceSpecies) } +
                            " (#" + review.sourceSpecies + ") • BDSP PB8 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • BDSP route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pa8", true)) {
                runCatching { LegendsArceusToSwordShieldPk8.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { SwordShieldSpeciesNames.name(review.sourceSpecies) } +
                            " (#" + review.sourceSpecies + ") • Legends: Arceus PA8 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Legends: Arceus route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pk9", true)) {
                runCatching { ScarletVioletToSwordShieldPk8.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { SwordShieldSpeciesNames.name(review.sourceSpecies) } +
                            " (#" + review.sourceSpecies + ") • Scarlet/Violet PK9 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Scarlet/Violet route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else if (file.extension.equals("pa9", true)) {
                runCatching { LegendsZaToSwordShieldPk8.review(file.readBytes()) }.fold(
                    onSuccess = { review ->
                        review.sourceNickname.ifBlank { SwordShieldSpeciesNames.name(review.sourceSpecies) } +
                            " (#" + review.sourceSpecies + ") • Legends: Z-A PA9 -> PK8 Legalise"
                    },
                    onFailure = { error ->
                        file.name + " • Legends: Z-A route blocked • " +
                            (error.message ?: "unsupported conversion")
                    }
                )
            } else {
                val parsed = runCatching { SwordShieldPokemonReadOnly.read(file.readBytes()) }.getOrNull()
                val pokemon = (parsed as? SwordShieldSlotRead.Pokemon)?.value
                if (pokemon == null) file.name + " • unreadable"
                else pokemon.nickname.ifBlank { SwordShieldSpeciesNames.name(pokemon.species) } +
                    " (#" + pokemon.species + ")" + (if (pokemon.shiny) " • Shiny" else "") + " • PK8"
            }
        }
        val builder = AlertDialog.Builder(this)
            .setTitle("PSE Bank • " + entries.size + " Sword/Shield routes")
            .setPositiveButton("Close", null)
        if (entries.isEmpty()) {
            builder.setMessage("No native Sword/Shield PK8, eligible Gen 1 PSE1, Gen 2 PSE2, Gen 3 PK3, Gen 4 PK4, Gen 5 PK5, Gen 6 PK6, Gen 7 PK7, Let's Go PB7, BDSP PB8, Legends: Arceus PA8, Scarlet/Violet PK9, or Legends: Z-A PA9 Bank entries are available.")
        } else {
            builder.setItems(labels.toTypedArray()) { _, index ->
                if (session !== bound) return@setItems
                val entry = entries[index]
                when {
                    entry.extension.equals("pse1", true) -> showSwordShieldGen1BankEntry(bound, entry)
                    entry.extension.equals("pse2", true) -> showSwordShieldGen2BankEntry(bound, entry)
                    entry.extension.equals("pk3", true) -> showSwordShieldGen3BankEntry(bound, entry)
                    entry.extension.equals("pk4", true) -> showSwordShieldGen4BankEntry(bound, entry)
                    entry.extension.equals("pk5", true) -> showSwordShieldGen5BankEntry(bound, entry)
                    entry.extension.equals("pk6", true) -> showSwordShieldGen6BankEntry(bound, entry)
                    entry.extension.equals("pk7", true) -> showSwordShieldGen7BankEntry(bound, entry)
                    entry.extension.equals("pb7", true) -> showSwordShieldLetsGoBankEntry(bound, entry)
                    entry.extension.equals("pb8", true) -> showSwordShieldBdspBankEntry(bound, entry)
                    entry.extension.equals("pa8", true) -> showSwordShieldLegendsArceusBankEntry(bound, entry)
                    entry.extension.equals("pk9", true) -> showSwordShieldScarletVioletBankEntry(bound, entry)
                    entry.extension.equals("pa9", true) -> showSwordShieldLegendsZaBankEntry(bound, entry)
                    else -> {
                        val result = runCatching { SwordShieldPokemonReadOnly.read(entry.readBytes()) }.getOrNull()
                        showSwordShieldPokemon(bound, "PSE Bank • " + entry.name,
                            result ?: SwordShieldSlotRead.Invalid("Bank record could not be read."))
                    }
                }
            }
        }
        builder.show()
    }


    private fun showSwordShieldLetsGoBankEntry(bound: SwitchReadSession, file: File) {
        if (session !== bound) return
        val directory = File(filesDir, "pse_bank").canonicalFile
        val entry = runCatching { file.canonicalFile }.getOrNull()
        val opened = runCatching {
            require(entry != null && entry.parentFile == directory && entry.isFile &&
                entry.name.startsWith("switch_lgpe_") && entry.extension.equals("pb7", true)) {
                "This is not a current Let's Go PSE Bank entry."
            }
            val bytes = entry.readBytes()
            val hash = SwordShieldPseBankRestoreEditing.sha256(bytes)
            require(entry.name == "switch_lgpe_${hash}.pb7") {
                "The PSE Bank filename no longer matches its native PB7 bytes."
            }
            val source = LetsGoToSwordShieldPk8.inspectSource(bytes)
            val trainer = SwordShieldTrainerReadOnly.read(bound.snapshot.bytesCopy())
            require(trainer.languageId == 2) {
                "This bounded Let's Go route currently requires an English Sword/Shield destination trainer."
            }
            Triple(bytes, source, trainer)
        }.getOrElse {
            AlertDialog.Builder(this).setTitle("Let's Go -> Sword/Shield blocked")
                .setMessage((it.message ?: "No safe conversion is available.") +
                    "\n\nThe PB7 Bank entry and Sword/Shield save remain unchanged.")
                .setPositiveButton("Close", null).show()
            return
        }
        val selected = entry ?: return
        val openedHash = SwordShieldPseBankRestoreEditing.sha256(opened.first)
        val loading = AlertDialog.Builder(this).setTitle("Prepare Let's Go -> Sword/Shield")
            .setMessage("Loading documented species metadata and building a reviewed PK8 preview from the exact selected PB7…")
            .setCancelable(false).create()
        loading.show()
        reader.execute {
            val prepared = runCatching {
                val metadata = loadGen7SwordShieldMetadata(
                    opened.second.species, opened.second.abilityNumber,
                    opened.second.abilityId
                )
                require(session === bound) { "The active save changed. Reopen PSE Bank." }
                val current = selected.readBytes()
                require(SwordShieldPseBankRestoreEditing.sha256(current) == openedHash) {
                    "The Let's Go Bank entry changed during review."
                }
                metadata to LetsGoToSwordShieldPk8.review(current, opened.third, metadata)
            }
            runOnUiThread {
                if (loading.isShowing) loading.dismiss()
                if (isFinishing || isDestroyed) return@runOnUiThread
