            boxMatch != null -> Triple(BdspPokemonArea.BOX, boxMatch.groupValues[1].toInt(), boxMatch.groupValues[2].toInt())
            partyMatch != null -> Triple(BdspPokemonArea.PARTY, 0, partyMatch.groupValues[1].toInt())
            else -> null
        }
        if (nativeTarget != null && !p.isEgg && p.form == 0 &&
            BdspPokemonEvolutionEditing.choices(p.species).isNotEmpty()) {
            content.addView(Button(this).apply {
                text = "Evolve Pokémon"
                isAllCaps = false
                setOnClickListener {
                    val source = selectedSourceUri
                    if (session === bound && source != null) startActivity(
                        Intent(this@SwitchReadOnlyActivity, SwitchBdspPokemonEvolutionActivity::class.java)
                            .setData(source)
                            .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                            .putExtra("pse.switch.pokemon.area", nativeTarget.first.name)
                            .putExtra("pse.switch.pokemon.box", nativeTarget.second)
                            .putExtra("pse.switch.pokemon.position", nativeTarget.third)
                            .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                    )
                }
            })
        }
        if (nativeTarget != null) content.addView(Button(this).apply {
            text = "Edit Pokémon"
            isAllCaps = false
            setOnClickListener {
                val source = selectedSourceUri
                if (session === bound && source != null) startActivity(
                    Intent(this@SwitchReadOnlyActivity, SwitchBdspPokemonNicknameActivity::class.java)
                        .setData(source)
                        .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                        .putExtra("pse.switch.pokemon.area", nativeTarget.first.name)
                        .putExtra("pse.switch.pokemon.box", nativeTarget.second)
                        .putExtra("pse.switch.pokemon.position", nativeTarget.third)
                        .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                )
            }
        })
        if (nativeTarget != null) content.addView(Button(this).apply {
            text = "Duplicate Pokémon"
            isAllCaps = false
            setOnClickListener {
                val source = selectedSourceUri
                if (session === bound && source != null) startActivity(
                    Intent(this@SwitchReadOnlyActivity, SwitchBdspPokemonDuplicateActivity::class.java)
                        .setData(source)
                        .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                        .putExtra("pse.switch.pokemon.area", nativeTarget.first.name)
                        .putExtra("pse.switch.pokemon.box", nativeTarget.second)
                        .putExtra("pse.switch.pokemon.position", nativeTarget.third)
                        .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                )
            }
        })
        if (nativeTarget != null && nativeTarget.first == BdspPokemonArea.BOX && !p.isEgg) {
            content.addView(Button(this).apply {
                text = "Swap with Pokémon in this Box"
                isAllCaps = false
                setOnClickListener {
                    val source = selectedSourceUri
                    if (session === bound && source != null) startActivity(
                        Intent(this@SwitchReadOnlyActivity, SwitchBdspPokemonSwapActivity::class.java)
                            .setData(source)
                            .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                            .putExtra("pse.switch.pokemon.box", nativeTarget.second)
                            .putExtra("pse.switch.pokemon.position", nativeTarget.third)
                            .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
