                            .setPositiveButton("Close", null).show()
                    } catch (error: Exception) {
                        AlertDialog.Builder(this).setTitle("Could not add to PSE Bank")
                            .setMessage(error.message ?: "The save could not be read again.")
                            .setPositiveButton("Close", null).show()
                    }
