        nav.addView(Button(this).apply {
            text = "Next"; isEnabled = box < 31
            setOnClickListener { dialog.dismiss(); if (session === bound) showScarletVioletBox(bound, box + 1) }
        }, LinearLayout.LayoutParams(0, -2, 1f))
        list.addView(nav)
        OmegaRubyUi.styleStorageList(this, list)
        dialog.show()
    }

    private fun showScarletVioletPokemon(bound: SwitchReadSession, location: String, read: ScarletVioletSlotRead) {
        if (session !== bound) return
        if (read !is ScarletVioletSlotRead.Pokemon) {
            AlertDialog.Builder(this).setTitle(location)
                .setMessage((read as? ScarletVioletSlotRead.Invalid)?.reason ?: "This slot is empty.")
                .setPositiveButton("Close", null).show()
            return
        }
        val p = read.value
        val gender = listOf("Male", "Female", "Genderless").getOrNull(p.gender) ?: "Unknown (${p.gender})"
        val detail = buildString {
            append("${ScarletVioletSpeciesNames.name(p.species)} (#${p.species}) • Form ${p.form}\n")
            append("Nickname: ${p.nickname.ifBlank { "None" }}\nGender: $gender\nEgg flag: ${p.isEgg}\n")
            append("Cached level: ${p.cachedLevel}\nEXP: ${p.experience}\n")
            append("Nature: ${ScarletVioletPokemonNatureEditing.describe(p.nature)}\n")
            append("Stat Nature: ${ScarletVioletPokemonNatureEditing.describe(p.statNature)}\n")
            append("Cached HP: ${p.currentHp}/${p.maximumHp}\n")
            append("Cached Atk/Def/Speed/SpA/SpD: ${p.cachedStats.joinToString(" / ")}\n")
            append("Shiny: ${if (p.shiny) "Yes" else "No"}\n")
            append("Held Item: ${ScarletVioletPokemonHeldItemEditing.name(p.heldItem)}\n")
            append("Ability: ${ScarletVioletAbilityCatalogue.describe(p.ability, p.abilityNumber)}\n")
            append("OT friendship: ${p.originalTrainerFriendship}\nHandling-trainer friendship: ${p.handlingTrainerFriendship}\n")
            val handler = when (p.currentHandler) { 0 -> "Original trainer"; 1 -> "Handling trainer"; else -> "Unknown (${p.currentHandler})" }
            append("Current handler: $handler\n")
            val effectiveTera = ScarletVioletTeraTypes.effective(p.teraTypeOriginal, p.teraTypeOverride)
            append("Original Tera Type: ${ScarletVioletTeraTypes.name(p.teraTypeOriginal)} (${p.teraTypeOriginal})\n")
            append("Saved Tera override: ${p.teraTypeOverride}\n")
            append("Effective Tera Type: ${ScarletVioletTeraTypes.name(effectiveTera)}\n")
            append("Native size: ${ScarletVioletPokemonScaleEditing.label(p.scale)}\n")
            append("Native size scalars: ${ScarletVioletPokemonSizeScalarEditing.describe(p.sizeScalars)}\n")
            append("Obedience Level: ${p.obedienceLevel}\n")
            append("Origin Game: ${ScarletVioletPokemonOriginGameEditing.name(p.originGame)} (#${p.originGame})\n")
            append("Battle Version: ${ScarletVioletPokemonBattleVersionEditing.name(p.battleVersion)} (#${p.battleVersion})\n")
            append("Form Argument: ${p.formArgument}\n")
            append("Capture Ball: ${ScarletVioletPokemonBallEditing.name(p.ball)} (#${p.ball})\n")
            append("Met Level: ${p.metLevel}\n")
            append("Hyper Training: ${ScarletVioletPokemonHyperTrainingEditing.summary(p.hyperTrainingFlags)}\n")
            append("HOME Tracker: ")
            append(if (ScarletVioletPokemonHomeTrackerEditing.hasTracker(p))
                "0x${ScarletVioletPokemonHomeTrackerEditing.trackerHex(p)}" else "None")
            append("\n")
            append("Battle Status: ")
            append(if (ScarletVioletPokemonStatusConditionEditing.hasStatus(p))
                "Raw 0x${ScarletVioletPokemonStatusConditionEditing.statusHex(p)}"
                else "Healthy (0x00000000)")
            append("\n")
            append("Recorded current TM moves: ${ScarletVioletPokemonTechnicalMachineEditing.recordedCurrentMoves(p)}\n")
            if (p.currentHandler in 0..1) {
                append("Friendship: ${ScarletVioletPokemonFriendshipEditing.currentFriendship(p)}")
                append(" (${ScarletVioletPokemonFriendshipEditing.handlerLabel(p)})\n")
            } else append("Friendship: unsupported current-handler value ${p.currentHandler}\n")
            append("Egg Date: ${ScarletVioletPokemonEggDateEditing.eggDate(p) ?: "Invalid/empty"}\n")
            append("Native egg location: ${p.eggLocation}\n")
            append("Met Date: ${ScarletVioletPokemonMetDateEditing.metDate(p) ?: "Invalid/empty"}\n")
            append("Native met location: ${p.metLocation}\n")
            append("Effective Tera Type follows native override semantics; battle/form effects and encounter legality are not evaluated.\n\n")
            append("Original trainer: ${p.originalTrainer}\n")
            append("Original Trainer gender: ${ScarletVioletPokemonOriginalTrainerGenderEditing.name(p.originalTrainerGender)}\n")
            if (p.handlingTrainer.isNotBlank()) {
                append("Handling Trainer: ${p.handlingTrainer.ifBlank { "Not set" }}\n")
                append("Handling Trainer gender: ${ScarletVioletPokemonHandlingTrainerGenderEditing.name(p.handlingTrainerGender)}\n")
                append("Handling Trainer language: ${ScarletVioletPokemonHandlingTrainerLanguageEditing.name(p.handlingTrainerLanguage)}\n")
            }
            append("Pokémon language: ${ScarletVioletPokemonLanguageEditing.name(p.language)}\n")
            append("Active Title: ${ScarletVioletPokemonAffixedTitleEditing.name(p.affixedRibbon)}\n")
            append("Pokérus: ${ScarletVioletPokemonPokerusEditing.describe(p.pokerusStrain, p.pokerusDays)}\n")
            append("Contest Condition: ${ScarletVioletPokemonContestConditionEditing.describe(p.contestStats)}\n")
            append("Box Markings: ${ScarletVioletPokemonMarkingEditing.describe(p.markingColors)}\n")
            append("TID16: ${p.tid}\nSID16: ${p.sid}\n")
            append("PID: ${p.pid.toString(16).uppercase()}\nEncryption constant: ${p.encryptionConstant.toString(16).uppercase()}\n\nMoves\n")
            p.moves.forEachIndexed { i, move -> append("${i + 1}. Move #${move.id} • PP ${move.pp} • PP Ups ${move.ppUps}\n") }
            append("Relearn move IDs: ${p.relearnMoves.joinToString(" / ")}\n\n")
            append("IVs (HP/Atk/Def/Speed/SpA/SpD): ${p.ivs.joinToString(" / ")}\n")
            append("EVs (same order): ${p.evs.joinToString(" / ")}\n\n")
            append("PK9 stored-data checksum passed. Cached party stats are outside that checksum and may be stale, especially in boxes. ")
            append("Native nickname editing is available for party and PC-box records. The dedicated ride record remains browse-only; legality and game-presence checks are not evaluated.")
        }
        val content = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        content.addView(TextView(this).apply {
            text = detail; textSize = 16f; setPadding(24, 16, 24, 16); setTextIsSelectable(true)
        })
        val boxMatch = Regex("^Box ([0-9]+) • Slot ([0-9]+)$").matchEntire(location)
        val partyMatch = Regex("^Party ([0-9]+)$").matchEntire(location)
        val nativeTarget = when {
            boxMatch != null -> Triple(ScarletVioletPokemonArea.BOX,
                boxMatch.groupValues[1].toInt(), boxMatch.groupValues[2].toInt())
            partyMatch != null -> Triple(ScarletVioletPokemonArea.PARTY, 0, partyMatch.groupValues[1].toInt())
            else -> null
        }
        if (nativeTarget != null && !p.isEgg && p.form == 0 &&
            ScarletVioletPokemonEvolutionEditing.choices(bound.snapshot.bytesCopy(), p.species).isNotEmpty()) {
            content.addView(Button(this).apply {
                text = "Evolve Pokémon"
                isAllCaps = false
                setOnClickListener {
                    val source = selectedSourceUri
                    if (session === bound && source != null) startActivity(
                        Intent(this@SwitchReadOnlyActivity, SwitchScarletVioletPokemonEvolutionActivity::class.java)
                            .setData(source)
                            .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
                            .putExtra("pse.switch.pokemon.area", nativeTarget.first.name)
                            .putExtra("pse.switch.pokemon.box", nativeTarget.second)
                            .putExtra("pse.switch.pokemon.position", nativeTarget.third)
                            .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                    )
                }
            })
        }
        if (nativeTarget != null && !p.isEgg && p.species != 1017 && p.species != 1024 &&
            ScarletVioletTeraTypes.isOriginalValid(p.teraTypeOriginal) &&
            ScarletVioletTeraTypes.isOverrideValid(p.teraTypeOverride)) {
            content.addView(Button(this).apply {
