    private fun showLetsGoGoParkArea(bound: SwitchReadSession, area: Int) {
        if (session !== bound || dashboardBusy) return
        val entries = bound.letsGoGoPark?.area(area) ?: return
        val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(24, 16, 24, 16) }
        for (entry in entries) root.addView(Button(this).apply {
            val shiny = if (entry.shiny) " ★" else ""
            val form = if (entry.form == 0) "" else " • Form ${entry.form}"
            text = "Slot ${entry.slot} • #${entry.species} ${entry.displayName}$shiny$form\n" +
                "Level ${goParkNumber(entry.level)} • CP ${entry.cp}"
            isAllCaps = false
            setOnClickListener { if (session === bound && !dashboardBusy) showLetsGoGoParkEntry(bound, entry) }
        })
        AlertDialog.Builder(this).setTitle("GO Park $area • ${entries.size}/50 occupied")
            .setView(ScrollView(this).apply { addView(root) })
            .setPositiveButton("All areas") { _, _ -> if (session === bound && !dashboardBusy) showLetsGoGoParkAreas(bound) }
            .setNegativeButton("Close", null).show()
    }

    private fun launchLetsGoGoParkImport(bound: SwitchReadSession) {
        if (session !== bound || dashboardBusy) return
        val source = selectedSourceUri ?: return
        startActivity(Intent(this, SwitchLetsGoGoParkImportActivity::class.java).setData(source)
            .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
            .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION))
    }

    private fun showLetsGoGoParkEntry(bound: SwitchReadSession, entry: LetsGoGoParkEntry) {
        if (session !== bound || dashboardBusy) return
        val gender = listOf("Male", "Female", "Genderless").getOrNull(entry.gender) ?: "Unknown (${entry.gender})"
        val date = if (entry.year in 2000..9999 && entry.month in 1..12 && entry.day in 1..31)
            "%04d-%02d-%02d".format(entry.year, entry.month, entry.day) else "Raw ${entry.capturedDate}"
        val detail = buildString {
            appendLine("GO Park ${entry.area} • Slot ${entry.slot} • Native index ${entry.index}")
            appendLine("Species: #${entry.species} ${LetsGoSpeciesNames.name(entry.species)}")
            appendLine("Nickname: ${entry.nickname.ifBlank { "None saved" }}")
            appendLine("Form: ${entry.form} • Gender: $gender • Shiny: ${if (entry.shiny) "Yes" else "No"}")
            appendLine("Level: ${goParkNumber(entry.level)} • CP: ${entry.cp} • Stored HP: ${entry.storedHp}")
            appendLine("GO IVs: HP ${entry.ivHp} / Attack ${entry.ivAttack} / Defense ${entry.ivDefense}")
            appendLine("Height: ${goParkNumber(entry.height)} m • Weight: ${goParkNumber(entry.weight)} kg")
            appendLine("Captured date: $date")
            appendLine("GO move IDs: ${entry.fastMoveId}, ${entry.chargedMoveId}")
            appendLine("Trainer: ${entry.username.ifBlank { "Not saved" }}")
            if (entry.secondUsername.isNotBlank()) appendLine("Secondary trainer string: ${entry.secondUsername}")
            appendLine("City: ${entry.city.ifBlank { "Not saved" }}")
            appendLine()
            append("All 21 native block CRCs passed before this record was read. This view does not infer encounter legality, convert the GP1 record, or move it into storage. Slot actions can export the exact GP1 bytes or clear this slot in a reviewed new save copy.")
        }
        AlertDialog.Builder(this).setTitle(entry.displayName + " • GO Park")
            .setView(ScrollView(this).apply { addView(TextView(this@SwitchReadOnlyActivity).apply {
                text = detail; textSize = 16f; setTextIsSelectable(true); setPadding(24, 16, 24, 16)
            }) }).setPositiveButton("Back to GO Park ${entry.area}") { _, _ ->
                if (session === bound && !dashboardBusy) showLetsGoGoParkArea(bound, entry.area)
            }.setNeutralButton("Slot actions") { _, _ -> launchLetsGoGoParkEditor(bound, entry) }
            .setNegativeButton("Close", null).show()
    }

    private fun launchLetsGoGoParkEditor(bound: SwitchReadSession, entry: LetsGoGoParkEntry) {
        if (session !== bound || dashboardBusy) return
        val source = selectedSourceUri ?: return
        startActivity(Intent(this, SwitchLetsGoGoParkActivity::class.java).setData(source)
            .putExtra("pse.switch.sha256", bound.snapshot.sourceSha256)
            .putExtra("pse.go_park.index", entry.index)
            .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION))
    }

    private fun goParkNumber(value: Float): String =
        if (!value.isFinite()) value.toString() else "%.2f".format(value)

    private fun showLetsGoDayCare(bound: SwitchReadSession) {
        if (session !== bound || dashboardBusy) return
        val read = bound.letsGoDayCare ?: return
        val detail = buildString {
            append("${read.version.displayName} • Day Care • Read-only\n\n")
            append("Native occupied flag: ${if (read.isOccupied) "Occupied" else "Empty"} (raw byte ${read.rawOccupiedByte})\n")
            append("Native step counter: ${read.stepCounter}\n\n")
            val p = read.pokemon
            if (p != null) {
                val gender = listOf("Male", "Female", "Genderless").getOrNull(p.gender) ?: "Unknown (${p.gender})"
                append("${if (read.isOccupied) "Deposited Pokémon" else "Inactive stored record"}: ${LetsGoSpeciesNames.name(p.species)} (#${p.species})\n")
                append("Form: ${p.form}\nGender: $gender\nSaved EXP: ${p.experience}\nNature ID: ${p.nature}\n")
                append("TID16: ${p.tid}\nSID16: ${p.sid}\nPID: ${p.pid.toString(16).uppercase().padStart(8, '0')}\n")
                append("Encryption constant: ${p.encryptionConstant.toString(16).uppercase().padStart(8, '0')}\n")
                append("Stored PB7 checksum passed.\n")
            } else if (read.isZeroStoredRecord) append("Stored record is all zero bytes.\n")
            else append("Stored Pokémon summary unavailable: ${read.recordUnavailableReason}\n")
            append("\nThe saved record has no party-stat tail. Level and HP are not supplied by this view. ")
            append("The occupied flag and unsigned step counter are shown exactly as stored; prefix bytes 1–3 remain undocumented here. ")
            append("No breeding, Egg, fee, earned EXP or withdrawal eligibility is inferred.\n\n")
            append("Native header (8 bytes; occupancy at 0, step counter at 4–7):\n${read.rawHeaderBytes.joinToString(" ") { "%02X".format(it) }}\n\n")
            append("Original stored record (232 encrypted bytes):\n${read.rawStoredBytes.joinToString(" ") { "%02X".format(it) }}\n\n")
            append("All 21 native block CRCs passed. Raw data remains available even when the inner record is unreadable. No normalization, deposit, withdrawal, repair, export, replacement or save writing. Legality is not evaluated.")
        }
        AlertDialog.Builder(this).setTitle("Day Care • Read-only")
            .setView(ScrollView(this).apply { addView(TextView(this@SwitchReadOnlyActivity).apply {
                text = detail; textSize = 16f; setTextIsSelectable(true); setPadding(24, 16, 24, 16)
            }) }).setPositiveButton("Close", null).show()
    }

    private fun showLetsGoPlayerLocation(bound: SwitchReadSession) {
        if (session !== bound || dashboardBusy) return
        val read = bound.letsGoPlayerLocation ?: return
        fun raw(bits: Long): String = bits.toString(16).uppercase().padStart(8, '0')
        fun transform(label: String, value: Float, bits: Long): String =
            "$label: ${if (value.isFinite()) value.toString() else "Non-finite"} • Raw 0x${raw(bits)}"
        val detail = buildString {
            append("${read.version.displayName} • Player Position • Read-only\n\n")
            append("Native map identifier: ${read.mapId}\n")
            append("Map identifier hex: ${read.mapId.toString(16).uppercase().padStart(16, '0')}\n")
            append("Map bytes: ${read.mapBytes.joinToString(" ") { "%02X".format(it) }}\n\n")
            append("Position\n")
            append(transform("X", read.x, read.positionBits[0])).append('\n')
            append(transform("Y", read.y, read.positionBits[2])).append('\n')
            append(transform("Z", read.z, read.positionBits[1])).append("\n\n")
            append("Scale\n")
            append(transform("X", read.scaleX, read.scaleBits[0])).append('\n')
            append(transform("Y", read.scaleY, read.scaleBits[2])).append('\n')
            append(transform("Z", read.scaleZ, read.scaleBits[1])).append("\n\n")
            append("Rotation quaternion\n")
            append(transform("X", read.rotationX, read.rotationBits[0])).append('\n')
            append(transform("Y", read.rotationY, read.rotationBits[2])).append('\n')
            append(transform("Z", read.rotationZ, read.rotationBits[1])).append('\n')
            append(transform("W", read.rotationW, read.rotationBits[3])).append("\n\n")
            if (!read.allTransformsFinite) append("One or more saved transform values are non-finite; their raw bits are retained without interpretation.\n\n")
            append("The map identifier is shown exactly as saved and is not guessed into a location name. ")
            append("All 21 native block CRCs passed before reading. No teleport, coordinate change, normalization, export, replacement or save writing.")
        }
        AlertDialog.Builder(this).setTitle("Player Position • Read-only")
            .setView(ScrollView(this).apply { addView(TextView(this@SwitchReadOnlyActivity).apply {
                text = detail; textSize = 16f; setTextIsSelectable(true); setPadding(24, 16, 24, 16)
            }) }).setPositiveButton("Close", null).show()
    }

