        if (page > 0) builder.setNegativeButton("Previous") { _, _ -> if (session === bound) showBdspBerryPlots(bound, page - 1) }
        if (page < lastPage) builder.setNeutralButton("Next") { _, _ -> if (session === bound) showBdspBerryPlots(bound, page + 1) }
        builder.show()
    }

